// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { submitNewOwnerForm, searchOwnersByLastName } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(110000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.getByRole("button", { name: "Owners" }).click();
    await page.getByRole("link", { name: "Add New" }).click();

    const playwrightRequest0: Record<string, any> = {
        "address": "5 Empty Lane",
        "city": "Madison",
        "firstName": "Petra",
        "lastName": "Petless",
        "telephone": "6085559999"
    };

    const response0 = await submitNewOwnerForm(
        page,
        getValue(playwrightRequest0, "firstName"),
        getValue(playwrightRequest0, "lastName"),
        getValue(playwrightRequest0, "address"),
        getValue(playwrightRequest0, "city"),
        getValue(playwrightRequest0, "telephone"),
    );

    // POST /petclinic/api/owners creates the owner and echoes it back.
    expect(response0.status()).toBe(201);
    const createdOwner = await response0.json();
    expect(createdOwner.firstName).toBe(getValue(playwrightRequest0, "firstName"));
    expect(createdOwner.lastName).toBe(getValue(playwrightRequest0, "lastName"));
    expect(createdOwner.address).toBe(getValue(playwrightRequest0, "address"));
    expect(createdOwner.city).toBe(getValue(playwrightRequest0, "city"));
    expect(createdOwner.telephone).toBe(getValue(playwrightRequest0, "telephone"));
    expect(createdOwner.id).toBeGreaterThan(0);
    // A newly created owner has no pets yet.
    expect(createdOwner.pets.length).toBe(0);
    expect(createdOwner.pets[0]).toBeUndefined();

    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    await searchOwnersByLastName(page, "Petless");

    // Searching by last name narrows the table to the owner just created. The row is
    // located by that owner's id rather than by name: owner names carry no unique
    // constraint, so re-running this test accumulates owners with the same last name.
    const petlessRow = page.locator("#ownersTable tbody tr", {
        has: page.locator(`a[href="/petclinic/owners/${createdOwner.id}"]`),
    });
    await expect(petlessRow).toHaveCount(1);
    await expect(petlessRow.locator("td").nth(0)).toContainText("Petra Petless");

    // An owner with no pets renders "0" in the "No. of pets" column added by this PR,
    // exercising the `|| 0` fallback in `{{ owner.pets?.length || 0 }}`.
    await expect(petlessRow.locator("td").nth(4)).toHaveText("0");
});
